package org.eclipse.kura.core.system;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import org.eclipse.kura.system.SystemService;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.osgi.service.component.ComponentContext;

public class ConfigurationValidationPropertyTest {

    private static final String[] SAVED_KEYS = { SystemService.KURA_CONFIG, SystemService.KURA_CUSTOM_CONFIG,
            SystemService.KEY_KURA_HOME_DIR, SystemService.KEY_KURA_FRAMEWORK_CONFIG_DIR,
            SystemService.KEY_KURA_USER_CONFIG_DIR, SystemService.KEY_KURA_CONFIGURATION_VALIDATION };

    @Rule
    public TemporaryFolder tempFolder = new TemporaryFolder();

    private final Map<String, String> previousSystemProperties = new HashMap<>();
    private SystemServiceImpl systemService;
    private boolean validationEnabled;

    @Before
    public void saveSystemProperties() {
        for (final String key : SAVED_KEYS) {
            this.previousSystemProperties.put(key, System.getProperty(key));
            System.clearProperty(key);
        }
    }

    @After
    public void restoreSystemProperties() {
        for (final Map.Entry<String, String> entry : this.previousSystemProperties.entrySet()) {
            if (entry.getValue() == null) {
                System.clearProperty(entry.getKey());
            } else {
                System.setProperty(entry.getKey(), entry.getValue());
            }
        }
    }

    @Test
    public void defaultsToEnabledWhenPropertyIsMissing() throws IOException {
        givenPropertiesFile("");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsEnabled();
    }

    @Test
    public void isEnabledWhenPropertyIsTrue() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=true\n");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsEnabled();
    }

    @Test
    public void isDisabledWhenPropertyIsFalse() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=false\n");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsDisabled();
    }

    @Test
    public void isDisabledWhenPropertyIsFalseIgnoringCaseAndWhitespace() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=  FALSE  \n");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsDisabled();
    }

    @Test
    public void defaultsToEnabledWhenPropertyValueIsInvalid() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=invalid\n");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsEnabled();
    }

    @Test
    public void customPropertiesFileOverridesBaseProperties() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=true\n");
        givenCustomPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=false\n");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsDisabled();
    }

    @Test
    public void systemPropertyOverridesPropertiesFiles() throws IOException {
        givenPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=true\n");
        givenCustomPropertiesFile(SystemService.KEY_KURA_CONFIGURATION_VALIDATION + "=true\n");
        givenSystemProperty(SystemService.KEY_KURA_CONFIGURATION_VALIDATION, "false");

        whenSystemServiceIsActivated();

        thenConfigurationValidationIsDisabled();
    }

    private void givenPropertiesFile(final String content) throws IOException {
        final File file = writeFile("kura.properties", content);
        System.setProperty(SystemService.KURA_CONFIG, file.toURI().toString());
    }

    private void givenCustomPropertiesFile(final String content) throws IOException {
        final File file = writeFile("kura_custom.properties", content);
        System.setProperty(SystemService.KURA_CUSTOM_CONFIG, file.toURI().toString());
    }

    private void givenSystemProperty(final String key, final String value) {
        System.setProperty(key, value);
    }

    private void whenSystemServiceIsActivated() {
        this.systemService = new SystemServiceImpl() {

            @Override
            protected String readResource(final String resource) {
                return null;
            }
        };
        this.systemService.activate(mock(ComponentContext.class));
        this.validationEnabled = this.systemService.isConfigurationValidationEnabled();
    }

    private void thenConfigurationValidationIsEnabled() {
        assertTrue(this.validationEnabled);
    }

    private void thenConfigurationValidationIsDisabled() {
        assertFalse(this.validationEnabled);
    }

    private File writeFile(final String name, final String content) throws IOException {
        final File file = new File(this.tempFolder.getRoot(), name);
        try (FileWriter writer = new FileWriter(file)) {
            writer.write(content);
        }
        return file;
    }
}
